// SQLite-backed Durable Object: one instance holds the download log and optional update emails.
// No IP addresses are stored - only the country/region Cloudflare derives from the request.
export class AnalyticsDB extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.sql = ctx.storage.sql;
    this.sql.exec("CREATE TABLE IF NOT EXISTS downloads (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, country TEXT, region TEXT, city TEXT, device TEXT, browser TEXT, ua TEXT, referer TEXT)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS shared_resumes (id INTEGER PRIMARY KEY AUTOINCREMENT, consent_ts TEXT NOT NULL, consent_text TEXT, filename TEXT, mime TEXT, file_b64 TEXT, text TEXT, text_hash TEXT, country TEXT, region TEXT, device TEXT)");
    // Additive migration: existing records keep null optional details.
    const resumeColumns = new Set(this.sql.exec("PRAGMA table_info(shared_resumes)").toArray().map((c) => c.name));
    for (const [name, type] of Object.entries({"submission_id": "TEXT", "phone": "TEXT", "phone_consent_ts": "TEXT", "browser": "TEXT", "device_category": "TEXT", "device_consent_ts": "TEXT", "latitude": "REAL", "longitude": "REAL", "location_accuracy": "REAL", "location_captured_at": "TEXT", "location_consent_ts": "TEXT", "details_consent_version": "TEXT", "details_consent_text": "TEXT", "google_maps_consent_ts": "TEXT"})) {
      if (!resumeColumns.has(name)) this.sql.exec("ALTER TABLE shared_resumes ADD COLUMN " + name + " " + type);
    }
    this.sql.exec("CREATE UNIQUE INDEX IF NOT EXISTS shared_resume_submission ON shared_resumes(submission_id)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS analyses (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, score INTEGER, job_title TEXT, company TEXT, missing TEXT, country TEXT, region TEXT, device TEXT)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS subscribers (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, email TEXT NOT NULL, country TEXT, region TEXT, device TEXT, source TEXT)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS admin_users (email TEXT PRIMARY KEY, pw_hash TEXT NOT NULL, created_ts TEXT NOT NULL, last_login TEXT)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS admin_sessions (tok_hash TEXT PRIMARY KEY, email TEXT NOT NULL, expires TEXT NOT NULL)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS login_fails (id INTEGER PRIMARY KEY AUTOINCREMENT, ip_hash TEXT NOT NULL, ts TEXT NOT NULL)");
    // One-time bootstrap: ADMIN_SEED secret = "email|pbkdf2$..." (a hash, never a plaintext password). Used only while admin_users is empty.
    if (env && env.ADMIN_SEED && this.sql.exec("SELECT count(*) AS n FROM admin_users").toArray()[0].n === 0) {
      const k = String(env.ADMIN_SEED).indexOf("|");
      if (k > 0) this.sql.exec("INSERT INTO admin_users (email,pw_hash,created_ts) VALUES (?,?,datetime('now'))", String(env.ADMIN_SEED).slice(0, k).trim().toLowerCase(), String(env.ADMIN_SEED).slice(k + 1).trim());
    }
  }
  logDownload(r) {
    this.sql.exec("INSERT INTO downloads (ts,country,region,city,device,browser,ua,referer) VALUES (?,?,?,?,?,?,?,?)", r.ts, r.country, r.region, r.city, r.device, r.browser, r.ua, r.referer);
  }
  addSubscriber(r) {
    const dup = this.sql.exec("SELECT id FROM subscribers WHERE lower(email)=lower(?) LIMIT 1", r.email).toArray();
    if (dup.length) return { ok: true, duplicate: true };
    this.sql.exec("INSERT INTO subscribers (ts,email,country,region,device,source) VALUES (?,?,?,?,?,?)", r.ts, r.email, r.country, r.region, r.device, r.source);
    return { ok: true };
  }
  addResume(r) {
    // Deduplicate retries by submission, never merge different people by resume text.
    if (r.submission_id) {
      const dup = this.sql.exec("SELECT id FROM shared_resumes WHERE submission_id=? LIMIT 1", r.submission_id).toArray();
      if (dup.length) return { ok: true, duplicate: true };
    }
    this.sql.exec("INSERT INTO shared_resumes (consent_ts,consent_text,filename,mime,file_b64,text,text_hash,country,region,device,submission_id,phone,phone_consent_ts,browser,device_category,device_consent_ts,latitude,longitude,location_accuracy,location_captured_at,location_consent_ts,details_consent_version,details_consent_text,google_maps_consent_ts) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", r.consent_ts, r.consent_text, r.filename, r.mime, r.file_b64, r.text, r.text_hash, r.country, r.region, r.device, r.submission_id, r.phone, r.phone_consent_ts, r.browser, r.device_category, r.device_consent_ts, r.latitude, r.longitude, r.location_accuracy, r.location_captured_at, r.location_consent_ts, r.details_consent_version, r.details_consent_text, r.google_maps_consent_ts);
    return { ok: true };
  }
  logAnalysis(r) {
    this.sql.exec("INSERT INTO analyses (ts,score,job_title,company,missing,country,region,device) VALUES (?,?,?,?,?,?,?,?)", r.ts, r.score, r.job_title, r.company, r.missing, r.country, r.region, r.device);
  }
  deleteRow(table, id) {
    if (!["downloads", "subscribers", "shared_resumes", "analyses"].includes(table)) return { ok: false };
    this.sql.exec("DELETE FROM " + table + " WHERE id=?", id);
    return { ok: true };
  }
  getResume(id) {
    return this.sql.exec("SELECT id,filename,mime,file_b64,text FROM shared_resumes WHERE id=?", id).toArray()[0] || null;
  }
  getResumeLocation(id) {
    return this.sql.exec("SELECT id,latitude,longitude,location_accuracy,location_captured_at,location_consent_ts,google_maps_consent_ts FROM shared_resumes WHERE id=?", id).toArray()[0] || null;
  }
  // ---- admin accounts / sessions ----
  getAdmin(email) {
    return this.sql.exec("SELECT email,pw_hash FROM admin_users WHERE email=?", String(email).toLowerCase()).toArray()[0] || null;
  }
  listAdmins() {
    return this.sql.exec("SELECT email,created_ts,last_login FROM admin_users ORDER BY created_ts").toArray();
  }
  addAdmin(email, hash) {
    if (this.getAdmin(email)) return { ok: false };
    this.sql.exec("INSERT INTO admin_users (email,pw_hash,created_ts) VALUES (?,?,datetime('now'))", email, hash);
    return { ok: true };
  }
  setPassword(email, hash) {
    this.sql.exec("UPDATE admin_users SET pw_hash=? WHERE email=?", hash, email);
    this.sql.exec("DELETE FROM admin_sessions WHERE email=?", email);
    return { ok: true };
  }
  deleteAdmin(email) {
    this.sql.exec("DELETE FROM admin_users WHERE email=?", email);
    this.sql.exec("DELETE FROM admin_sessions WHERE email=?", email);
    return { ok: true };
  }
  createSession(tokHash, email, days) {
    this.sql.exec("DELETE FROM admin_sessions WHERE expires < datetime('now')");
    this.sql.exec("INSERT INTO admin_sessions (tok_hash,email,expires) VALUES (?,?,datetime('now',?))", tokHash, email, "+" + days + " day");
    this.sql.exec("UPDATE admin_users SET last_login=datetime('now') WHERE email=?", email);
    this.sql.exec("DELETE FROM login_fails WHERE ts < datetime('now','-1 day')");
  }
  checkSession(tokHash) {
    const r = this.sql.exec("SELECT s.email FROM admin_sessions s JOIN admin_users u ON u.email=s.email WHERE s.tok_hash=? AND s.expires > datetime('now')", tokHash).toArray()[0];
    return r ? { email: r.email } : null;
  }
  deleteSession(tokHash) {
    this.sql.exec("DELETE FROM admin_sessions WHERE tok_hash=?", tokHash);
  }
  recordFail(ipHash) {
    this.sql.exec("INSERT INTO login_fails (ip_hash,ts) VALUES (?,datetime('now'))", ipHash);
  }
  recentFails(ipHash) {
    return this.sql.exec("SELECT count(*) AS n FROM login_fails WHERE ip_hash=? AND ts >= datetime('now','-15 minutes')", ipHash).toArray()[0].n;
  }
  // Fixed 1-hour-window rate limiter for public endpoints. Keyed by a SHA-256 of the
  // client IP (same treatment as login_fails - raw IPs are never stored).
  rateHit(key, limit) {
    const hour = new Date().toISOString().slice(0, 13);
    this.sql.exec("CREATE TABLE IF NOT EXISTS rate_limits (k TEXT PRIMARY KEY, n INTEGER NOT NULL)");
    this.sql.exec("DELETE FROM rate_limits WHERE substr(k, -13) < ?", hour);
    const k = key + ":" + hour;
    this.sql.exec("INSERT INTO rate_limits (k,n) VALUES (?,1) ON CONFLICT(k) DO UPDATE SET n=n+1", k);
    return this.sql.exec("SELECT n FROM rate_limits WHERE k=?", k).toArray()[0].n > limit;
  }
  // Fixed 1-day-window cap (UTC day), same hashed-IP keys as rateHit. Separate table so
  // the hourly cleanup above never touches daily counters.
  rateHitDay(key, limit) {
    const day = new Date().toISOString().slice(0, 10);
    this.sql.exec("CREATE TABLE IF NOT EXISTS rate_daily (k TEXT PRIMARY KEY, n INTEGER NOT NULL)");
    this.sql.exec("DELETE FROM rate_daily WHERE substr(k, -10) < ?", day);
    const k = key + ":" + day;
    this.sql.exec("INSERT INTO rate_daily (k,n) VALUES (?,1) ON CONFLICT(k) DO UPDATE SET n=n+1", k);
    return this.sql.exec("SELECT n FROM rate_daily WHERE k=?", k).toArray()[0].n > limit;
  }
  // ---- exports / read-only SQL ----
  exportTable(t) {
    const cols = { downloads: "id,ts,country,region,city,device,browser,referer,ua", subscribers: "id,ts,email,country,region,device,source", analyses: "id,ts,score,job_title,company,missing,country,region,device", shared_resumes: "id,consent_ts,consent_text,filename,mime,text,country,region,device,submission_id,phone,phone_consent_ts,browser,device_category,device_consent_ts,latitude,longitude,location_accuracy,location_captured_at,location_consent_ts,details_consent_version,details_consent_text,google_maps_consent_ts" }[t];
    if (!cols) return [];
    return this.sql.exec("SELECT " + cols + " FROM " + t + " ORDER BY id").toArray();
  }
  exportAll() {
    const out = { exported_at: new Date().toISOString() };
    for (const t of ["downloads", "subscribers", "analyses", "shared_resumes"]) out[t] = this.exportTable(t);
    return out;
  }
  runQuery(q) {
    q = String(q || "").trim().replace(/;\s*$/, "");
    if (!/^(select|with)\b/i.test(q)) return { error: "Only SELECT queries are allowed." };
    if (q.includes(";")) return { error: "One statement at a time." };
    if (/\b(insert|update|delete|drop|alter|create|replace|pragma|attach|detach|vacuum|reindex|analyze|savepoint|release|rollback|commit|begin)\b/i.test(q)) return { error: "Only read-only SELECT queries are allowed." };
    if (/admin_|login_fails|sqlite_|_cf_/i.test(q)) return { error: "That table is not available here." };
    try {
      const cur = this.sql.exec(q);
      const rows = [];
      for (const row of cur) { rows.push(row); if (rows.length >= 1000) return { rows, capped: true }; }
      return { rows };
    } catch (e) { return { error: String(e.message || e).slice(0, 300) }; }
  }
  report() {
    const q = (s) => this.sql.exec(s).toArray();
    return {
      total: q("SELECT count(*) AS n FROM downloads")[0].n,
      today: q("SELECT count(*) AS n FROM downloads WHERE ts >= datetime('now','-1 day')")[0].n,
      week: q("SELECT count(*) AS n FROM downloads WHERE ts >= datetime('now','-7 day')")[0].n,
      byCountry: q("SELECT coalesce(country,'?') AS k, count(*) AS n FROM downloads GROUP BY 1 ORDER BY 2 DESC LIMIT 20"),
      byDevice: q("SELECT coalesce(device,'?') AS k, count(*) AS n FROM downloads GROUP BY 1 ORDER BY 2 DESC"),
      byDay: q("SELECT substr(ts,1,10) AS k, count(*) AS n FROM downloads GROUP BY 1 ORDER BY 1 DESC LIMIT 30"),
      downloads: q("SELECT id,ts,country,region,city,device,browser,ua,referer FROM downloads ORDER BY id DESC LIMIT 500"),
      analyses: (() => {
        const a = q("SELECT count(*) AS n, round(avg(score),1) AS avg FROM analyses WHERE score IS NOT NULL")[0];
        const rows = q("SELECT missing FROM analyses ORDER BY id DESC LIMIT 3000");
        const cnt = {};
        rows.forEach((r) => { try { JSON.parse(r.missing || "[]").forEach((k) => { cnt[k] = (cnt[k] || 0) + 1; }); } catch (e) {} });
        return {
          total: q("SELECT count(*) AS n FROM analyses")[0].n,
          week: q("SELECT count(*) AS n FROM analyses WHERE ts >= datetime('now','-7 day')")[0].n,
          avg: a.avg,
          buckets: q("SELECT CASE WHEN score>=80 THEN '80-100' WHEN score>=60 THEN '60-79' WHEN score>=40 THEN '40-59' ELSE '0-39' END AS k, count(*) AS n FROM analyses WHERE score IS NOT NULL GROUP BY 1 ORDER BY 1 DESC"),
          gaps: Object.entries(cnt).sort((x, y) => y[1] - x[1]).slice(0, 20).map(([k, n]) => ({ k, n })),
          titles: q("SELECT job_title AS k, count(*) AS n FROM analyses WHERE job_title<>'' GROUP BY lower(job_title) ORDER BY 2 DESC LIMIT 15"),
          companies: q("SELECT company AS k, count(*) AS n FROM analyses WHERE company<>'' GROUP BY lower(company) ORDER BY 2 DESC LIMIT 15"),
          recent: q("SELECT id,ts,score,job_title,company,missing,country,region,device FROM analyses ORDER BY id DESC LIMIT 100"),
        };
      })(),
      resumes: q("SELECT id,consent_ts,filename,mime,length(file_b64) AS fsize,substr(text,1,160) AS preview,length(text) AS tlen,country,region,device,submission_id,phone,phone_consent_ts,browser,device_category,device_consent_ts,latitude,longitude,location_accuracy,location_captured_at,location_consent_ts,details_consent_version,details_consent_text,google_maps_consent_ts FROM shared_resumes ORDER BY id DESC LIMIT 500"),
      subscribers: q("SELECT id,ts,email,country,region,device FROM subscribers ORDER BY id DESC LIMIT 1000"),
    };
  }
}

function dbStub(env) { return env.DB.get(env.DB.idFromName("main")); }
function parseUA(ua) {
  ua = ua || "";
  let device = "Other";
  if (/Android/i.test(ua)) device = "Android";
  else if (/iPhone|iPad|iPod/i.test(ua)) device = "iOS";
  else if (/CrOS/i.test(ua)) device = "ChromeOS";
  else if (/Windows/i.test(ua)) device = "Windows";
  else if (/Macintosh|Mac OS X/i.test(ua)) device = "Mac";
  else if (/Linux/i.test(ua)) device = "Linux";
  let browser = "Other";
  if (/Edg\//.test(ua)) browser = "Edge";
  else if (/OPR\//.test(ua)) browser = "Opera";
  else if (/Firefox\//.test(ua)) browser = "Firefox";
  else if (/Chrome\//.test(ua)) browser = "Chrome";
  else if (/Safari\//.test(ua)) browser = "Safari";
  if (/bot|crawl|spider|curl|wget|python|headless/i.test(ua)) browser = "Bot/script";
  return { device, browser };
}
function geo(request) {
  const cf = request.cf || {};
  return { country: cf.country || null, region: cf.region || null, city: cf.city || null };
}

async function trackedExtensionZip(request, env, ctx) {
  try {
    const ua = request.headers.get("user-agent") || "";
    const g = geo(request), d = parseUA(ua);
    const ref = request.headers.get("referer") || "";
    ctx.waitUntil(dbStub(env).logDownload({ ts: new Date().toISOString().replace("T", " ").slice(0, 19), country: g.country, region: g.region, city: g.city, device: d.device, browser: d.browser, ua: ua.slice(0, 400), referer: ref.slice(0, 200) }).catch(() => {}));
  } catch (e) {}
  return extensionZip();
}

function locationJson(data, status = 200) {
  return new Response(JSON.stringify(data), {status, headers:{"content-type":"application/json", "cache-control":"no-store", ...SEC_H}});
}
function validCoordinate(lat, lng) { return Number.isFinite(lat) && Math.abs(lat) <= 90 && Number.isFinite(lng) && Math.abs(lng) <= 180; }
async function googleQuota(request, env) {
  const limit = Math.min(10000, Math.max(1, Number.parseInt(env.GOOGLE_MAPS_DAILY_LIMIT || "100", 10) || 100));
  return (await tooMany(request, env, "google-location", 20)) || (await dbStub(env).rateHitDay("google-location-project", limit));
}
async function googleRequest(url, options = {}) {
  try {
    const response = await fetch(url, {...options, signal:AbortSignal.timeout(8000)});
    if (!response.ok) throw new Error("provider");
    return await response.json();
  } catch { throw new Error("Google Maps is unavailable. Please try again later."); }
}
function radioPayload(body) {
  const out = {considerIp:false};
  if (body.wifiAccessPoints != null) {
    if (!Array.isArray(body.wifiAccessPoints) || body.wifiAccessPoints.length > 20) throw new Error("Provide up to 20 Wi-Fi access points.");
    const seen = new Set();
    out.wifiAccessPoints = [];
    for (const ap of body.wifiAccessPoints) {
      const mac = typeof ap?.macAddress === "string" ? ap.macAddress.toLowerCase() : "";
      // Drop local/multicast/reserved MACs instead of inadvertently using IP fallback.
      if (!/^(?:[0-9a-f]{2}:){5}[0-9a-f]{2}$/.test(mac) || (parseInt(mac.slice(0,2),16) & 3) || mac.startsWith("00:00:5e:") || mac === "00:00:00:00:00:00" || seen.has(mac)) continue;
      const item = {macAddress:mac};
      if (ap.signalStrength != null) {
        if (!Number.isFinite(ap.signalStrength) || ap.signalStrength < -128 || ap.signalStrength > -10) throw new Error("Invalid Wi-Fi signal strength.");
        item.signalStrength = ap.signalStrength;
      }
      seen.add(mac);out.wifiAccessPoints.push(item);
    }
  }
  if (body.cellTowers != null) {
    if (!Array.isArray(body.cellTowers) || body.cellTowers.length > 20 || !["gsm","wcdma","lte","nr"].includes(body.radioType)) throw new Error("Provide a supported radio type and up to 20 towers.");
    out.radioType = body.radioType;
    out.cellTowers = body.cellTowers.map(t => {
      const field = body.radioType === "nr" ? "newRadioCellId" : "cellId";
      const max = body.radioType === "nr" ? 68719476735 : body.radioType === "gsm" ? 65535 : 268435455;
      if (!t || !Number.isInteger(t[field]) || t[field] < 0 || t[field] > max || !Number.isInteger(t.mobileCountryCode) || t.mobileCountryCode < 0 || t.mobileCountryCode > 999 || !Number.isInteger(t.mobileNetworkCode) || t.mobileNetworkCode < 0 || t.mobileNetworkCode > 999) throw new Error("Invalid cell tower data.");
      const item = {[field]:t[field],mobileCountryCode:t.mobileCountryCode,mobileNetworkCode:t.mobileNetworkCode};
      if (t.locationAreaCode != null || body.radioType === "gsm") {
        if (!Number.isInteger(t.locationAreaCode) || t.locationAreaCode < 0 || t.locationAreaCode > (body.radioType === "nr" ? 16777215 : 65535)) throw new Error("Invalid cell area code.");
        item.locationAreaCode=t.locationAreaCode;
      }
      return item;
    });
  }
  if ((out.wifiAccessPoints?.length || 0) < 2 && !out.cellTowers?.length) throw new Error("Google Geolocation needs two usable Wi-Fi access points or cell-tower data. Use browser location on this website.");
  return out;
}
async function googleGeolocate(request, env) {
  if (!sameOrigin(request)) return locationJson({error:"Request blocked."},403);
  let body;try { body=await request.json(); } catch { return locationJson({error:"Invalid request."},400); }
  if (body?.location_consent !== true || body?.google_radio_consent !== true || body?.consent_version !== DETAILS_CONSENT_VERSION) return locationJson({error:"Explicit consent to send device radio signals to Google is required."},400);
  let payload;try { payload=radioPayload(body); } catch(e) { return locationJson({error:e.message},400); }
  if (!env.GOOGLE_MAPS_API_KEY) return locationJson({error:"Google Maps is not configured. Browser location remains available."},503);
  if (await googleQuota(request, env)) return locationJson({error:"Location lookup limit reached. Please try later."},429);
  try {
    const data=await googleRequest("https://www.googleapis.com/geolocation/v1/geolocate?key="+encodeURIComponent(env.GOOGLE_MAPS_API_KEY),{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});
    if (!validCoordinate(data.location?.lat,data.location?.lng) || !Number.isFinite(data.accuracy) || data.accuracy < 0) throw new Error("Google could not determine a location from those signals.");
    return locationJson({location:{latitude:data.location.lat,longitude:data.location.lng,accuracy:data.accuracy,captured_at:new Date().toISOString()},source:"google_geolocation",attribution:"Google Maps",notice:"Estimated location, not a verified address. Result is not stored by ResumeFit."});
  } catch(e) { return locationJson({error:e.message},502); }
}
async function reverseGeocode(latitude, longitude, env) {
  if (!validCoordinate(latitude,longitude)) throw new Error("Invalid stored location.");
  const params=new URLSearchParams({latlng:latitude+","+longitude,key:env.GOOGLE_MAPS_API_KEY});
  const data=await googleRequest("https://maps.googleapis.com/maps/api/geocode/json?"+params);
  if (data.status === "ZERO_RESULTS") return null;
  if (data.status !== "OK" || typeof data.results?.[0]?.formatted_address !== "string") throw new Error("Google Maps could not return an address. Check API configuration or try later.");
  return data.results[0].formatted_address;
}
async function adminAddress(request, env, db) {
  // Called only after admin authentication, POST and same-origin validation.
  const form=await request.formData().catch(()=>new FormData());
  const id=Number(form.get("id"));
  if (!Number.isInteger(id) || id < 1) return new Response("Invalid resume ID",{status:400,headers:ADMIN_H});
  const row=await db.getResumeLocation(id);
  if (!row) return new Response("Resume not found",{status:404,headers:ADMIN_H});
  if (!row.location_consent_ts || !row.google_maps_consent_ts) return new Response("Google Maps consent was not provided for this submission.",{status:403,headers:ADMIN_H});
  let address=null,error="",status=200;
  if (!env.GOOGLE_MAPS_API_KEY) {error="Google Maps is not configured. Add GOOGLE_MAPS_API_KEY as a Cloudflare Worker secret.";status=503;}
  else if (await googleQuota(request,env)) {error="Location lookup limit reached. Please try later.";status=429;}
  else {try {address=await reverseGeocode(row.latitude,row.longitude,env);} catch(e) {error=e.message;status=502;}}
  const content=error ? '<p class="err">'+esc(error)+'</p>' : address ? '<div style="border:1px solid #555;padding:16px"><p>'+esc(address)+'</p><span translate="no" style="color:white;font-size:14px;font-weight:400;white-space:nowrap">Google Maps</span></div>' : '<p>No address found for these coordinates.</p>';
  const html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shared location - ResumeFit admin</title><style>'+ADMIN_CSS+'</style></head><body><main class="wrap"><a href="/admin?tab=resumes">Back to shared resumes</a><div class="card"><h1>Address near the shared location</h1><p>Coordinates: '+esc(row.latitude)+', '+esc(row.longitude)+' · Reported accuracy: '+esc(row.location_accuracy)+' m</p><p>Captured: '+esc(row.location_captured_at)+'</p>'+content+'<p class="muted">This is an address lookup near a recorded device location, not proof of residence or the person&#39;s current location. The lookup does not improve the original accuracy.</p></div></main></body></html>';
  return new Response(html,{status,headers:{...ADMIN_H,"content-type":"text/html;charset=utf-8","referrer-policy":"no-referrer"}});
}

const DETAILS_CONSENT_VERSION = "2026-09-25-v2";
const DETAILS_CONSENT_TEXT = {
  google: "Allow my shared coordinates to be sent to Google Maps for an address lookup and map display. Optional; this does not improve location accuracy.",
  phone: "Share my mobile number so the ResumeFit team can contact me about my resume.",
  device: "Share my device category, operating system and browser with the ResumeFit team to help troubleshoot the service.",
  location: "Share my current location and its accuracy with the ResumeFit team so they can understand where submissions come from.",
};
function consentedDetails(input, ua, now = Date.now()) {
  const d = input && typeof input === "object" ? input : {};
  const out = {phone:null,phone_consent_ts:null,browser:null,device_category:null,device_consent_ts:null,latitude:null,longitude:null,location_accuracy:null,location_captured_at:null,location_consent_ts:null,details_consent_version:null,details_consent_text:null,google_maps_consent_ts:null};
  const agreed = d.phone_consent === true || d.device_consent === true || d.location_consent === true || d.google_maps_consent === true;
  if (agreed && d.consent_version !== DETAILS_CONSENT_VERSION) throw new Error("Please reload to review the current optional sharing choices.");
  const ts = new Date(now).toISOString();
  const wording = [];
  if (d.phone_consent === true) {
    const phone = typeof d.phone === "string" ? d.phone.trim().replace(/[ ()-]/g, "") : "";
    if (!/^\+[1-9]\d{7,14}$/.test(phone)) throw new Error("Enter a valid mobile number with country code, or disable mobile sharing.");
    out.phone = phone; out.phone_consent_ts = ts; wording.push(DETAILS_CONSENT_TEXT.phone);
  }
  if (d.device_consent === true) {
    out.browser = parseUA(ua).browser;
    out.device_category = /iPad|Tablet|Android(?!.*Mobile)/i.test(ua || "") ? "Tablet" : /Mobile|iPhone|iPod/i.test(ua || "") ? "Mobile" : /Windows|Macintosh|Linux|CrOS/i.test(ua || "") ? "Desktop" : "Unknown";
    out.device_consent_ts = ts; wording.push(DETAILS_CONSENT_TEXT.device);
  }
  if (d.location_consent === true) {
    const loc = d.location;
    if (!loc || !Number.isFinite(loc.latitude) || Math.abs(loc.latitude) > 90 || !Number.isFinite(loc.longitude) || Math.abs(loc.longitude) > 180 || !Number.isFinite(loc.accuracy) || loc.accuracy < 0 || loc.accuracy > 20000000) throw new Error("Invalid location. Retry or disable location sharing.");
    const captured = typeof loc.captured_at === "string" ? Date.parse(loc.captured_at) : NaN;
    if (!Number.isFinite(captured) || captured > now + 60000 || now - captured > 600000) throw new Error("Location expired. Capture it again or disable location sharing.");
    out.latitude = loc.latitude; out.longitude = loc.longitude; out.location_accuracy = loc.accuracy;
    out.location_captured_at = new Date(captured).toISOString(); out.location_consent_ts = ts; wording.push(DETAILS_CONSENT_TEXT.location);
  }
  if (d.google_maps_consent === true) {
    if (!out.location_consent_ts) throw new Error("Share a location before enabling Google Maps lookup.");
    out.google_maps_consent_ts = ts; wording.push(DETAILS_CONSENT_TEXT.google);
  }
  if (agreed) { out.details_consent_version = DETAILS_CONSENT_VERSION; out.details_consent_text = wording.join(" "); }
  return out;
}

async function shareResume(request, env) {
  let b = {};
  try { b = await request.json(); } catch (e) {}
  if (!b || b.consent !== true) return jsonResponse({ error: "No consent" }, 400);
  let details;
  try { details = consentedDetails(b.details, request.headers.get("user-agent")); }
  catch (e) { return jsonResponse({ error: e.message }, 400); }
  const submissionId = b.submission_id == null ? null : String(b.submission_id);
  if (submissionId !== null && !/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(submissionId)) return jsonResponse({ error: "Invalid submission ID." }, 400);
  const text = String(b.text || "").trim().slice(0, 60000);
  if (text.length < 50) return jsonResponse({ error: "Resume text missing" }, 400);
  let file = String(b.file_b64 || "");
  if (file.length > 1400000 || !/^[A-Za-z0-9+/=]*$/.test(file)) file = "";
  const hash = [...new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text)))].map((x) => x.toString(16).padStart(2, "0")).join("");
  const g = geo(request), d = parseUA(request.headers.get("user-agent"));
  const r = await dbStub(env).addResume({ consent_ts: new Date().toISOString().replace("T", " ").slice(0, 19), consent_text: String(b.consent_text || "").slice(0, 400), filename: String(b.filename || "").slice(0, 200) || null, mime: String(b.mime || "").slice(0, 100) || null, file_b64: file || null, text, text_hash: hash, country: g.country, region: g.region, device: d.device, submission_id: submissionId, ...details });
  return jsonResponse(r);
}

async function subscribe(request, env) {
  let b = {};
  try { b = await request.json(); } catch (e) {}
  const email = String(b.email || "").trim().slice(0, 200);
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return jsonResponse({ error: "Enter a valid email." }, 400);
  if (badEmail(email)) return jsonResponse({ error: "Please use your real email address (temporary inboxes are not accepted)." }, 400);
  const g = geo(request), d = parseUA(request.headers.get("user-agent"));
  const r = await dbStub(env).addSubscriber({ ts: new Date().toISOString().replace("T", " ").slice(0, 19), email, country: g.country, region: g.region, device: d.device, source: "extension" });
  return jsonResponse(r);
}

function esc(s) { return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]); }
function safeEq(a, b) {
  a = String(a || ""); b = String(b || "");
  if (!a || !b || a.length !== b.length) return false;
  let x = 0; for (let i = 0; i < a.length; i++) x |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return x === 0;
}
function toCsv(rows, cols) {
  const q = (v) => '"' + String(v == null ? "" : v).replace(/"/g, '""') + '"';
  return [cols.join(",")].concat(rows.map((r) => cols.map((c) => q(r[c])).join(","))).join("\n");
}

async function tooMany(request, env, scope, limit, daily) {
  const ip = request.headers.get("cf-connecting-ip") || "?";
  const key = scope + ":" + (await sha256b64("rf-rl:" + ip));
  return daily ? await dbStub(env).rateHitDay(key, limit) : await dbStub(env).rateHit(key, limit);
}
